"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["8236"],{1907(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>h,frontMatter:()=>r,contentTitle:()=>s,toc:()=>c,assets:()=>l});var i=JSON.parse('{"id":"reference/register/howtos/registerWithInitialConfiguration","title":"How to register systems with an initial configuration (Pre-Configure)?","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/register/howtos/registerWithInitialConfiguration.md","sourceDirName":"reference/register/howtos","slug":"/reference/register/howtos/registerWithInitialConfiguration","permalink":"/personal-av-docs/docs/reference/register/howtos/registerWithInitialConfiguration","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/register/howtos/registerWithInitialConfiguration.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to register systems with an initial configuration (Pre-Configure)?","sidebar_label":"How to register systems with an initial ","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/register/howtos/registerWithInitialConfiguration","format":"md"}}'),o=n(4848),a=n(8453);let r={title:"How to register systems with an initial configuration (Pre-Configure)?",sidebar_label:"How to register systems with an initial ",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/register/howtos/registerWithInitialConfiguration",format:"md"},s,l={},c=[];function d(e){let t={a:"a",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/register/howtos/registerWithInitialConfiguration",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:"How to register systems with an initial configuration (Pre-Configure)?\nInitial configuration\nTo simplify your deployment you can pre-designate the configuration you want AirVantage to apply when it connects the first time. The Pre-configure System(s) window offers several pre-defined workflows for pre-configuration.\nBy default, it shows you the Basic Workflow, which includes:\nCommunication intervals with AirVantage and scheduled reports\nSet the device UI administrator password\nFirmware version\nConfiguration template\nThe other pre-defined workflows are\nInstall AAF Application\nand\nConfigure ALMS AMR\n(available only in the ALMS AMR offer class on an MP70 or LX60 with Wi-Fi + GNSS + Telemetry device).\nUsing one or more of the pre-defined workflows is recommended because they enforce an order of operations that is required for a successful deployment. If you create a custom workflow using individual actions (described below), you must ensure that the order of operations is correct. For example, ensure that the AAF password is set before installing an AAF application.\nOnce the systems start communicating with AirVantage, the operations will be executed one after another, to end up with the desired configuration.\nPlease note that this initial configuration will undertake one operation step only at each device communication interval. The overall configuration may take few device heartbeat periods. The device will reboot one or more times during this process.\nConfigure device communication\nHeartbeat\nis the time interval that the device will communicate to AirVantage.\nAll relevant jobs that are in queue in ALMS are triggered based on the heartbeat. This timer cannot be set to less than 15 minutes, unless your account is in the ALMS AMR offer class. Note that the heartbeat will consume around 1.4 Kb of data.\nClicking\nMore\nexpands the window to show two additional timers that relate to the status icon that appears on the Monitor > Systems page. You can enter a timeout value to change the green icon to amber and from amber to red.\nStatus report\nis the time interval for collecting the group of status data from the device for display in AirVantage.\nFor information on status report data and airtime usage, see\nDefault Status Report Parameters and associated data consumption\n.\nAdditional datasets\nis the time interval for collecting a user-defined set of data from the device for display in AirVantage. You need to create a Dataset data set in AirVantage in advance to configure this option.\nTo create a dataset, go to the Configure > Datasets page. Click on the\n+\nto begin the process.\nSet Device UI Administrator Password\nEasily set a unique password for the device at deployment. Sierra Wireless recommends changing the unique default passwords on all devices.\nWhen using MSCI, the password is required to allow ALMS to remotely change the ACEmanager password. Enter the ACEmanager password used to login to this device directly. Once registered, it\u2019s recommended to update your passwords.\nIt is also used to enable the ALEOS server-initiated communication option, and as the M3DA password for ALEOS Application Framework (AAF) applications.\nFirmware version\nThis option lets you apply a firmware update to the systems that you are adding to AirVantage.\nPrior to selecting this option ensure that you are selecting a valid upgrade version. Some older versions of AirLink ALEOS firmware have dependencies that may require an incremental update. In that case apply the valid version. You will be able to apply the latest version once the systems are registered and communicating with AirVantage.\nConfiguration template\nYou need to create an ALEOS configuration template in AirVantage to apply that template when the new system registers.\nTo create a template, go to the Configure > Templates page. Click the\n+\nto begin the process. You have the option to create a new template from an existing device that you already have communicating into ALMS (select\nFrom a System\n) or\nFrom an Application (from Scratch)\nif not.\nInstall AAF Application workflow\nYou can add the Install AAF Application workflow to the Basic workflow if you wish to install an AAF application such as AVTA.\nTo add an AAF application:\nSet an AAF password. The AAF password can be 4 to 100 characters long and can contain a mixture of letters, numbers, and/or special characters. The password is case sensitive.\nSelect the desired AAF application from the list or by searching (click the search icon).\nTo install additional AAF applications, add \u201CInstall Application\u201D as an individual action (see\nCreating a Custom Workflow\nbelow).\nConfigure ALMS AMR workflow\nThis workflow is available only to the ALMS Advanced Mobility Reporting (AMR) offer class, and for telemetry-capable systems. For more information about prerequisites for ALMS AMR, see\nReporting\n.\nTo configure ALMS AMR:\nSet an AAF password.\nInstall the latest firmware for your device. For an AirLink MP70, ensure that ALEOS 4.9.0 or later is installed. For an AirLink LX60 with Wi-Fi + GNSS + Telemetry, ensure that ALEOS 4.13.0 or later is installed.\nConfigure Telemetry for your system by ensuring that Driver Behavior Detection, Location Service, Direct Vehicle Bus Data Collection and Dead Reckoning are enabled. Note that the settings for Configuring Telemetry differ slightly depending on the ALEOS version. However, the final functionality is the same.\nInstall the latest version of the AirLink Vehicle Telemetry Application (AVTA).\nSelect the Start Application. This is the application that starts running after the Install Application process is complete. When configuring ALMS AMR, select the same version of AVTA for both Install Application and Start Application.\nSet the AVTA password.\nClick\nPre-configure\n.\nCreating a Custom Workflow\nYou can customize pre-configuration by adding actions to an existing Workflow or by creating your own workflow from the individual actions available in the left column of the Pre-configure Systems window.\nMost of the individual actions are described in the sections above, and include:\nSet Device UI Administrator Password\nConfigure communication\nInstall Firmware\nApply Template\nSet AAF Password\nInstall Application\nSet AVTA password\nApply Labels\nReboot System\nClick\nShow individual actions\nto display the list of available actions, and then drag and drop actions into the main window to create a workflow.\nTo remove an action, click its \u201Cbin\u201D icon (\n) or drag the action back into the left-hand column."})]})}function h(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var i=n(6540);let o={},a=i.createContext(o);function r(e){let t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);